'use strict';

// MODULES //

var tape = require( 'tape' );
var isDataSet = require( '@stdlib/plot/vega/base/assert/is-dataset' );
var nestedarrays2tidy = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof nestedarrays2tidy, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns a list of data sets', function test( t ) {
	var out = nestedarrays2tidy( [ [ [ 1, 2 ] ], [ [ 3, 4 ] ] ], [ 'data1', 'data2' ], [ 'x', 'y' ] );
	t.strictEqual( out.length, 2, 'returns expected value' );
	t.strictEqual( isDataSet( out[ 0 ] ), true, 'returns expected value' );
	t.strictEqual( isDataSet( out[ 1 ] ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns data sets having specified names', function test( t ) {
	var out = nestedarrays2tidy( [ [ [ 1, 2 ] ], [ [ 3, 4 ] ] ], [ 'beep', 'boop' ], [ 'x', 'y' ] );
	t.strictEqual( out[ 0 ].name, 'beep', 'returns expected value' );
	t.strictEqual( out[ 1 ].name, 'boop', 'returns expected value' );
	t.end();
});

tape( 'the function converts a list of nested arrays to "tidy" data sets', function test( t ) {
	var expected;
	var actual;
	var out;
	var i;

	out = nestedarrays2tidy( [ [ [ 1, 2 ], [ 3, 4 ] ], [ [ 5, 6 ], [ 7, 8 ] ] ], [ 'data1', 'data2' ], [ 'x', 'y' ] );

	actual = out[ 0 ].toJSON().values;
	for ( i = 0; i < actual.length; i++ ) {
		actual[ i ] = actual[ i ].toJSON();
	}
	expected = [
		{
			'x': 1,
			'y': 2
		},
		{
			'x': 3,
			'y': 4
		}
	];
	t.deepEqual( actual, expected, 'returns expected value' );

	actual = out[ 1 ].toJSON().values;
	for ( i = 0; i < actual.length; i++ ) {
		actual[ i ] = actual[ i ].toJSON();
	}
	expected = [
		{
			'x': 5,
			'y': 6
		},
		{
			'x': 7,
			'y': 8
		}
	];
	t.deepEqual( actual, expected, 'returns expected value' );
	t.end();
});

tape( 'the function supports specifying field names', function test( t ) {
	var expected;
	var actual;
	var out;
	var i;

	out = nestedarrays2tidy( [ [ [ 1, 2 ] ], [ [ 3, 4 ] ] ], [ 'data1', 'data2' ], [ 'a', 'b' ] );

	actual = out[ 0 ].toJSON().values;
	for ( i = 0; i < actual.length; i++ ) {
		actual[ i ] = actual[ i ].toJSON();
	}
	expected = [
		{
			'a': 1,
			'b': 2
		}
	];
	t.deepEqual( actual, expected, 'returns expected value' );

	actual = out[ 1 ].toJSON().values;
	for ( i = 0; i < actual.length; i++ ) {
		actual[ i ] = actual[ i ].toJSON();
	}
	expected = [
		{
			'a': 3,
			'b': 4
		}
	];
	t.deepEqual( actual, expected, 'returns expected value' );
	t.end();
});

tape( 'the function returns an empty list if provided an empty list', function test( t ) {
	var out = nestedarrays2tidy( [], [], [ 'x', 'y' ] );
	t.deepEqual( out, [], 'returns expected value' );
	t.end();
});
